"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["1569"],{5998(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>p,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>d});var i=JSON.parse('{"id":"how-to/hardware/samples/hl-mqtt-devkit","title":"Getting started with HL module on RaspberryPI or Linux-based system","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/samples/hl-mqtt-devkit.md","sourceDirName":"how-to/hardware/samples","slug":"/how-to/hardware/samples/hl-mqtt-devkit","permalink":"/personal-av-docs/docs/how-to/hardware/samples/hl-mqtt-devkit","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/samples/hl-mqtt-devkit.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Getting started with HL module on RaspberryPI or Linux-based system","sidebar_label":"Getting started with HL module on Raspbe","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/samples/hl-mqtt-devkit","format":"md"}}'),a=t(4848),o=t(8453);let s={title:"Getting started with HL module on RaspberryPI or Linux-based system",sidebar_label:"Getting started with HL module on Raspbe",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/samples/hl-mqtt-devkit",format:"md"},r,d={},l=[];function c(e){let n={a:"a",code:"code",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(n.p,{children:[":::note Edition\n",(0,a.jsx)(n.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(n.a,{href:"https://doc.airvantage.net/av/howto/hardware/samples/hl-mqtt-devkit",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsxs)(n.p,{children:["Getting started with HL module on RaspberryPI or Linux-based system\nThis tutorial describes how to create a communication with AirVantage Cloud from a\nLinux-based system\nequiped with a\nHL wireless module\n.\nThe Linux-based system may be a RasberryPI or an Ubuntu PC.\nThe following use cases are covered:\nSending some custom data such as sensor value or application data from the Linux-based system to the AirVantage Cloud\nSending some commands or configuration from AirVantage Cloud to the Linux-based system\nTo implement this solution, MQTT protocol will be used\nTo achieve the above objective, following main steps are covered:\nHow to setup your device: Hardware connection, AT command interface and IP connectivity\nHow to register your device on AirVantage\nHow to communicate with AirVantage using MQTT\nAlthough, the guideline has been tested on Raspberry PI, it can easily be adapted to other Linux-based system.\nPrerequisite\nHL demo board + Antena + Power adaptor\nAirPrime HL series Module\nSIM card with data call plan\nUSB-to-Serial Converter\nHost system with Linux-based OS (e.g. RaspberryPI/Raspian, PC/Ubuntu, Mac/MacOS, etc)\nHave an account on AirVantage server : eu.airvantage.net\nPart references used in this tutorial\nAirPrime HL6528 module\nRaspberryPI B+\nAirPrime HL Series DevKit\nUSB-to-Serial cable\n1 /\nIP Connectivity\n2 /\nServer Application\n3 /\nMQTT data exchange\nAny issues ?\nIf you encounter any issue to set up your device, don\u2019t hesitate to use the\ndeveloper forum\nto benefit from the developer community experience.\nStep 1: Setting the IP Connectivity\nThis step starts with connecting the HL module to your Raspberry, and verify that it is attached to a Linux virtual serial device port (e.g. /dev/ttyUSB0).\nAT Command\ninterface should then be in place to enable the host application to control the HL Module.\nFinally,\nIP Connectivity\nis created using PPP dial-up to enable host applications to communicate with remote servers.\nConnect Hardware\nPlace the HL Module into the demo board\u2019s module socket. To ensure the correct orientation of the HL Module, use the\ndot\nmark, printed on the top right corner, as reference. It should be aligned with the\ndot\nmark visible within the demo board socket. Then place the shielding cover on the module.\nConnect the \u201CUART1_MAIN\u201D port of the HL demo board to your RaspberryPI, using a USB-to-Serial converter cable.\nConnect the antenna to the \u201C2G/3G/4G RF MAIN\u201D connector.\nInsert a SIM card into the \u201CSIM1\u201D slot.\nPower-on the demo board with the power adaptor on \u201CVBAT\u201D jack\nVerify Hardware Connectivity\nYour USB-to-Serial adapter should be listed when entering \u201Clsusb\u201D linux command on your host system.\nType in the \u201Cdmesg | grep tty\u201D linux command. Check the log to identify the device port (e.g. /dev/ttyUSB0) that has been associated to the HL demo board\nCheck AT-Command Interface\nUse a serial terminal (e.g. minicom) to make sure that the AT interface can be established. To install minicom proceed as follow (internet access required):\nsudo apt-get install minicom\nInitialize the serial terminal to open the device port (e.g. /dev/ttyUSB0) on which the HL module is attached to, for instance:\nsudo minicom -D\n/dev/ttyUSB0\nThe following AT commands shall be entered within minicom to perform some sanity checking:\nAT\n: expected response\nOK\n. If not, make sure the board is powered on (the\nVBAT\nled should be on) and check minicom baudrate setting (default HL baudrate should be 115200), using\nminicom -s\nAT+CPIN?\n: expected response\nREADY\nif not, SIM PIN may be entered using the\nAT+CPIN\ncommand. e.g.\nAT+CPIN=\u201C1234\u201D\nAT+IPR?\n: the operating baudrate should be returned, please use this baudrate in the remaining tutorial\nAT+CREG?\n: to check the network registration status, expected response +CREG:x,1 (registered, home network) or +CREG:x,5 (roaming)\nAT+CGREG?\n: to check the GPRS registration status, expected response +CGREG:x,1 (registered, home network) or +CGREG:x,5 (roaming)\nAT+CSQ\n: returns \u201CRSSI\u201D,\u201CBER\u201D. RSSI indicates the signal strength in dBm, a value of 99 reflects no signal detected or not known\nIssue\nAT+CGSN\ncommand to retrieve module\u2019s IMEI, please note the IMEI, it will be used in upcoming tutorial steps\nIssue\nAT+KGSN=3\ncommand to retrieve module\u2019s Serial Number, please note the S/N for future use\nAT Commands Integration in the Device\nIn the above hands-on sections, we were able to manually send AT-Commands, using minicom. This sub-section aims to facilitate the AT-Command support within your device application.\nIntegration Helper\nThe aforementioned AT commands must be issued programmatically within your device application. And the response must be filtered and analyzed by the device application. For instance, the returned IMEI should be extracted from\nAT+CGSN\nresponse, IMEI is required to register the HL module on AirVantage platform.\nFor your convenience, a\nsample AT command line tool\ncan be adapted and integrated into your device application to rapidly gain AT-Command capabilities and to control the HL module.\nThe provided sample AT command can also be used as is, as follow:\n./hl-atcmd   -d devicePort   -b baudrate   -f atcmd-filter   at-cmd\nFor instance:\n./hl-atcmd   -d /dev/ttyUSB0   -b 115200    -f AT+CGSN    AT+CGSN\nwill return the filtered response which is the IMEI. Full response will be returned if no filter is specified.\n./hl-atcmd   -d /dev/ttyUSB0   -b 115200    -f +KGSN:    \u2018AT+KGSN=\u201C3\u201D\u2019\nwill return the filtered response which is the Serial Number. Full response will be returned if no filter is specified.\nSIM PIN may be entered as follow:\n./hl-atcmd   -d /dev/ttyUSB0   -b 115200    \u2018AT+CPIN=\u201C1234\u201D\u2019\nAny AT-commands as documented in the AT-command specification can be executed using this command line (shell scriptable)\nIf the AT command is not responding, make sure that device port and the baudrate (\nAT+IPR?\n) are both correct.\nSetup PPP\nPPP daemon (pppd) is available on Linux-based system\nIt can be installed on RaspberryPI as follow (internet access required):\nsudo apt-get install\nppp\nPPP dial-up configuration is defined by a pppOptionFile, located in the /etc/ppp/peers directory. It is depending on a chatscript file (in /etc/chatscripts directory).\nThe content of pppOptionFile is carrier specific and can be generated with pppconfig utility, refer to \u201Cman pppconfig\u201D pages.\nOrange-France specific pppOptionFile and chatscript are provided\nhere\nas example.\nNote that the device port and the baud rate are stated in the option file\nLaunch PPP\nStart PPP daemon by specifying the filename of the pppOptionFile (located in\n/etc/ppp/peers\ndirectory) as follow\nsudo\npppd\ncall\npppOptionFile\n&\nThe following statements in the log indicate a successful outcome of the PPP daemon:\n\u201Clocal IP address\u2026\u201D, \u201Cremote IP address\u2026\u201D, \u201Cip-up finished\u201D\nPPP interface (e.g. ppp0) should be listed with associated IP address upon ifconfig commmand\nIP connectivity can be assessed with a ping command (e.g. ping ",(0,a.jsx)(n.a,{href:"http://www.google.com",children:"www.google.com"}),')\nWhen you will need to close the IP connectivity later, it is highly recommended not to stop the PPP daemon with\nCTRL-C\n. Proceed as following to properly terminate the PPP session:\nIssue\nps -ef | grep pppd\nin the console\nIdentify the\npid\nassociated to the running\npppd\nprocess\nIssue\nsudo kill -s SIGHUP pid\nso the pppd will have the modem to hangup properly the data call.\nRegister System/Device (if not already done)\nAt this point, if your device has not been registered on AirVantage server, please proceed as follow:\nRegister System/Device\nFor PC/Ubuntu users, your internet connection is now handled by the HL module. It is recommended to use another PC to access AirVantage Web Portal\nLog into\nAirVantage Web portal\nGo to Register activity\nClick on the \u201CAirPrime HL Series\u201D section\nSelect your HL series module\nFill the Serial Number field, as captured previously using AT+KGSN=3\nFill the IMEI field, as captured previously using AT+CGSN\nSet a name and click on Register\nIn Step 1, we\u2019ve covered how to:\nConnect HL Module to RaspberryPI\nSend AT Commands to HL Module\nRetrieve HL Modules\u2019s IMEI & Serial Number using AT+CGSN & AT+KGSN=3 commands\nUse PPP dial-up to obtain IP Connectivity\nRegister the Device on AirVantage using HL Module\u2019s IMEI as identifier\nStep 2: Design the Server Application\nAn embedded application on device-side (e.g. RaspberryPI) is interfacing with a server-side application on AirVantage in order to exchange predefined data over a predefined communication protocol and authentication scheme.\nThis step starts describing the Application Model concept which is used to define a server-side application.\nThe Application Model XML file is customized to define the set data to be exchanged between the device and AirVantage.\nThe finalized XML file is packaged as Application Package then released and published onto AirVantage, so that it can be associated to user-selected System/device(s).\nDefine\nServer-side\nApplication\nServer-side application is defined by an\nApplication Model\n(a XML file)\nAirVantage uses this XML file to figure out how to deal with the device about\nCommunication Protocol\n,\nAuthentication\nand\nData Exchange\n(e.g. variable, settings, commands)\nCreate an Application Model XML file on your desktop/laptop (e.g. start with the example described below)\nWithout Application Model, the server will ignore all communication from your device.\nDefine Data Model\nBelow is a sample Application Model XML file defining the server-side application for the\nGreenhouse\nembedded application:\nIn the\napp:application\ntag, the\ntype\nattribute defines the unique identifier (\ncom.test.airvantage.app\n) of the application whose\nname\nis\nAirVantage Greenhouse\nwith a\nrevision\nnumber\n0.0.1\nThe Device-Server communication protocol is MQTT, as defined by the\nType\nattibute of the subsequent\ncommunication/protocol\ntag.\nThe data model is described in the\n<data>\ntag. It has an\nasset\n(\u201Cmachine\u201D) comprising two\nvariables\n(\u201Ctemperature\u201D & \u201Chumidity\u201D) of\ntype\ndouble, and one \u201CTurnOn\u201D\ncommand\nto control a \u201CLight\u201D\nparameter\nof\ntype\nboolean\nYou can modify the content of\n<data>\nto define a custom data model that your device application will be sending to or receiving from AirVantage.\nYou\u2019ll also have to define appropriate values for\nType\n,\nname\nand\nrevision\nattributes of\napp:application\ntag.\n<?xml version="1.0" encoding="ISO-8859-1"?>\n<app:application\nxmlns:app="',(0,a.jsx)(n.a,{href:"http://www.sierrawireless.com/airvantage/application/1.0",children:"http://www.sierrawireless.com/airvantage/application/1.0"}),'"\ntype="com.test.airvantage.app"\nname="AirVantage Greenhouse"\nrevision="0.0.1">\n<capabilities>']}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{children:'&lt;communication&gt;\n  &lt;protocol comm-id="IMEI" type="MQTT" /&gt;\n&lt;/communication&gt;\n\n&lt;data&gt;\n  &lt;encoding type="MQTT"&gt;\n    &lt;asset default-label="Greenhouse" id="machine"&gt;\n      &lt;variable default-label="Temperature" path="temperature" type="double"/&gt;\n      &lt;variable default-label="Humidity" path="humidty" type="double"/&gt;\n      &lt;command path="TurnOn" default-label="Turn on"&gt;\n        &lt;parameter id="Light" default-label="Light" type="boolean" /&gt;\n      &lt;/command&gt;\n    &lt;/asset&gt;\n  &lt;/encoding&gt;\n&lt;/data&gt;\n'})}),"\n",(0,a.jsx)(n.p,{children:'</capabilities>\n</app:application>\nCreate Application Package\nSave the the above Application Model to file with\napp\nfile extension (e.g. appmodel.app)\nZip the app file (e.g.\nappmodel.zip\n)\nThe filename of this zip file is only used for uploading process. AirVantage does not keep track of this zip filename. Only the XML content will be tracked by AirVantage.\nLog into\nAirVantage Web portal\nGo on Develop Activity > My Apps\nClick on the Release button\nRelease Application\nSelect your zip file (e.g.\nappmodel.zip\n)\nOpen Advanced settings and select\nI want to publish my application after releasing it\nFinally, click on Start\nEdit System/Device\nGo on Inventory > Systems\nSelect your system and click on the Edit icon\nSearch your Application\nClick on Search application\nIn the new dialog box, select the My Application tab\nSearch your application using its name (AirVantage Greenhouse)\nAssociate Application to your System/Device\nClick on the application to select it\nClick on the padlock and configure the password\nClick on Save in the right top corner\nClick on the Monitor icon to monitor your system\nIn the grid, select the newly created system and click on the \u201CActivate\u201D action\nIn Step 2, we\u2019ve covered how to:\nDefine the server-side application using Application Model\nCustomize Data Model that your device application will be sending to or receiving from AirVantage\nCreate the Application Package\nRelease and Publish the server-side application (package)\nAssign the server-side application to support the client-side application in the Device\nStep 3: MQTT data exchange with AirVantage Server\nMQTT\nis a lightweight publish/subscribe messaging protocol. A Device/Client application can\npublish\na message to MQTT broker under a uniquely named\ntopic\n. The server then instantly relays this message to other connected Device/Client applications having subscribed to the same named\ntopic\n.\nOne-to-one and one-to-many IoT messaging approaches mechanism can thus come to life.\nAirVantage server implements MQTT Broker functionalities. It has the ability to receive, to retain then to relay MQTT messages. AirVantage supports MQTT QoS Level 1 (messages delivered at least once with confirmation required).\nThis section starts with hands-on steps showing you how to publish messages to and receive data from AirVantage, using Mosquitto command line tools. Key integration aspects of MQTT client into your device application is then highlighted.\nAny client implementing MQTT can be used to exchange data with AirVantage. In this tutorial, we will use\nMosquitto\n, an open source solution implementing MQTT which can installed on the host (e.g. run the following command for RaspberryPI or PC running Ubuntu) as follow (internet access required):\nsudo apt-get install mosquitto-clients\nPublish MQTT Messages\nMQTT messaging content exchanged between the Device and AirVantage Server is defined by Application Model and the payload should be JSON encoded:\nEach sample of a\nvariable\nhas a timestamp (elapsed ms since Jan-1970) and a value. It is possible to send a collection (or array) of sample at once.\nThe variable is identified by it\u2019s asset id and the path\nFor instance, the following MQTT message to be published contains 2 samples of\nTemperature\nand\nHumidity\nvariable\nas defined in\nStep 2-\u201CDefine Data Model\u201D\n:\n[\n{ "machine.temperature": [\n{"timestamp": 1425937636000, "value":"21"},\n{"timestamp": 1425939843000, "value":"20.9"} ]\n},\n{ "machine.humidity": [\n{"timestamp": 1425937636000, "value":"37"},\n{"timestamp": 1425939843000, "value":"38"} ]\n}\n]\nThe above message shall be published to topic: \u201C%IMEI/messages/json\u201D, where %IMEI is the IMEI of the module as retrieved in Step 1\nPublish message to AirVantage, using Mosquitto command line:\nSave the above sample JSON message into a file (e.g. pub-msg.txt)\nPublish the file\u2019s content to AirVantage, as follow\nmosquitto_pub -h eu.airvantage.net -t %IMEI/messages/json -f pub-msg.txt -u %IMEI -P %password\n(where %IMEI is the IMEI of the module as retrieved in Step 1, %password is the password defined in Step 2)\nView Pusblished data on Web portal\nLog into\nAirVantage Web portal\nGo to Monitor > Systems\nSearch for your Systems/Device using filters (e.g. Label, IMEI)\nClick on your System/Device to view monitoring page\nScroll down to \u201CLast Communication\u201D panel to view data published by the Device\n\u201CTimeline\u201D option can be used to view history events related to Device communication with AirVantage server\nSubscribing to MQTT topic\nIn order to receive data from AirVantage, the device application must subscribe to the topic: \u201C%IMEI/tasks/json\u201D\nLet\u2019s do this using Mosquitto command line as follow:\nmosquitto_sub -h eu.airvantage.net -t %IMEI/tasks/json -u %IMEI -P %password\n(where %IMEI is the IMEI of the module as retrieved in Step 1, %password is the password defined in Step 2)'}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:['Incoming data will be displayed as they arrive\u2026 now let\u2019s send some data\nSending MQTT data to Device from Web portal\nGo to Monitor > Systems\nSearch for your Device using filters (e.g. Label, IMEI)\nClick on your Device to view monitoring page\nClick on the \u201CMore\u201D button\n(located on top right), then select \u201CCustom Command\u201D\nBase on the Greenhouse Application Model (excerpt below), the \u201CTurn On\u201D command can be sent to the Device from AirVantage Web portal:\n<command path="TurnOn" default-label="Turn on">\n<parameter id="Light" default-label="Light" type="boolean" />\nSelect the action in the Command listbox and specify the corresponding parameters (e.g. Turn on Light)\nClick \u201CSend Command\u201D to fire the MQTT message to your Device\nReceiving MQTT Messages\nThe incoming MQTT message should be displayed by the previous\nmosquitto_sub\ncommand as follow:\n[{\n"uid":"9142df4c0b884683993521a3d5cf97f1",\n"timestamp":1426022121930,\n"command":{"id":"machine.TurnOn","params":{"Light":true}}\n}]\nThis message is JSON encoded and must be decoded by the Device (handled by the callback function) as follow:\nuid\nis the unique id of this MQTT message\ntimestamp is the jan-1970 ms elapsed timestamp of this message\ncommand\nobject is composed of :\nid:\nasset id\n(machine) and the\ncommand path\n(TurnOn)\nparameter id (Light) set to\ntrue\nAcknowledging incoming MQTT Messages\nUpon receiving an incoming MQTT command message (sent by AirVantage), the Device shall return an acknowledge message. This latter must enclose \u201Cuid\u201D and \u201Cstatus\u201D keys, the optional \u201Cmessage\u201D key may be provided. Below is a sample ack message to the incoming message as shown in the previous section.\n[{\n"uid":"9142df4c0b884683993521a3d5cf97f1",\n"status":"OK"\n}]\nThis ack message is JSON encoded and must be published to \u201C%IMEI/acks/json\u201D Topic:\nuid\nis the unique id of the incoming MQTT command message to be acknowledged\nstatus\nbeing OK or ERROR\noptional\nmessage\nkey may be included to provided information on the error\nPublish ack message to AirVantage, using Mosquitto command line:\nPaste the above sample ACK JSON message to a text editor, and replace the uid value by the one located in the incoming message (displayed by mosquitto_sub)\nSave the ack message content a file (e.g. ack-msg.txt)\nPublish the file\u2019s content to AirVantage, as follow\nmosquitto_pub -h eu.airvantage.net -t %IMEI/acks/json -f ack-msg.txt -u %IMEI -P %password\n(where %IMEI is the IMEI of the module as retrieved in Step 1, %password is the password defined in Step 2)\nMQTT Client Integration in the Device\nIn the above hands-on steps, we were able to manually send messages to and receive data from AirVantage, using Mosquitto command line tools. This sub-section provides additional highlights on the integration of MQTT client into your device application. Addressing RaspberryPI\u2019s GPIO is also briefly described.\nMQTT Client Integration in the Device\nThe device application must implement MQTT Client functionalities in order to programmatically publish messages and to receive messages pertaining to subscribed topics. The specification can be found on\n',(0,a.jsx)(n.a,{href:"http://mqtt.org",children:"http://mqtt.org"}),"\nThere are various MQTT libraries available on the web that can be leveraged to easily gain MQTT support in the device application.\nMost MQTT Client libraries expose 4 main functions:\nOpen Connection\nThe device application should call this function first with the following parameters:\nAirVantage MQTT server URL and port number: (eu.airvantage.net:1883)\nDevice IMEI (retrieved in step 1,\n\u201CSend AT commands\u201D\n), for authentication purposes\nPassword (as defined in step 2,\n\u201CAssociate your Application to your System/Device\u201D\n)\nMessage Publishing\nThe device application calls this function to\npublish\nthe provided MQTT message (to be formatted as shown in step 3.2) to the specified\nTopic\n(URI style)\nThe publishing\ntopic\nshall be \u201C%IMEI/messages/json\u201D, where %IMEI is the IMEI of the module as retrieved in Step 1\nTopic Subscription\nThe device app calls this function along with a\nTopic\nto\nsubscribe\nto and a callback function to decode and parse the incoming MQTT message pertaining to the\ntopic\nThe subscription\ntopic\nshall be \u201C%IMEI/tasks/json\u201D, where %IMEI is the IMEI of the module as retrieved in Step 1\nIncoming message published to \u201C%IMEI/tasks/json\u201D topic, should be acknowledged by publishing an ack message to\nTopic\n\u201C%IMEI/acks/json\u201D\nClose Connection\nNote that, in the previous hands-on section, the publishing command (mosquitto_pub) and subscription command (mosquitto_sub), are both encapsulated by Open connection and Close connection operations\nControlling RaspberryPI's GPIO\nControlling RaspberryPI\u2019s GPIO\nThe\nwiringPI\nlibrary can be easily integrated into the RaspberryPI in order to control GPIO.\nFor instance, to turn on a LED wired to the GPIO-0 of the RaspberryPI when the device receives the above\nTurnOn Light\ncommand\nBelow is the sample code:\n#include <wiringPi.h>\n...\nwiringPiSetup();\npinMode(0, OUTPUT);\n...\nif (turnOnLight)\n{\ndigitalWrite(0, HIGH);\n}\nelse\n{\ndigitalWrite(0, LOW);\n}\nTroubleshooting & Testing\nRefer to this\ntutorial\nfor further information on how to troubleshoot the connection and to interact with system/device\nIn Step 3, we\u2019ve covered how to:\nMQTT Client integration into device and connection with AirVantage\nFormatting, encoding and Publishing MQTT message\nViewing and collecting posted data on AirVantage\nSending MQTT data to Device from AirVantage\nSubscribing, receiving, decoding incoming MQTT messages\nSending command to RaspberryPI\u2019s GPIO port\nMQTT Sample Code\nAs described in the previous steps, enabling MQTT support in the device application requires the integration of MQTT protocol (may leveraging existing libraries). It also requires the implementation of JSON payload encoding/decoding and parsing/mapping of sensor/actuator/application data to the data model as defined in the application model.\nRefer to below sample applications (C code) for integration reference.\nGreenhouse\nThis sample (used in the above steps) publishes emulated Temperature and Humidity to AirVantage, and receives \u201CTurnOn\u201D command from AirVantage.\nYou may adapt this code to fit your needs.\nMQTT Spooler\nThis app automatically converts CVS data to MQTT messages prior publishing to server. It also automatically converts incoming MQTT messages (pertaining to a subscribed Topic) to CSV data. This app could be reused as a quick integration option (no need to deal with MQTT code) with your existing sensor/actuator based application."]}),"\n"]})]})}function p(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var i=t(6540);let a={},o=i.createContext(a);function s(e){let n=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(o.Provider,{value:n},e.children)}}}]);